function openRawUsage(lotId){const lot=state.breadLots.find(x=>x.id===lotId);if(!lot)return;const f=document.querySelector('#psRawUsageForm'),root=document.querySelector('#psRawUsageRows');f.elements.breadLotId.value=lotId;const reqs=rawRequirements(lot);root.innerHTML=reqs.length?reqs.map(req=>{const options=state.rawLots.filter(r=>r.ingredientKey===req.key&&!r.deletedAt&&rawLotUsable(r)&&String(r.receivedDate||'')<=String(lot.date||'9999-12-31')&&(!r.expiryDate||String(r.expiryDate)>=String(lot.date||''))).sort((a,b)=>String(a.receivedDate||'9999').localeCompare(String(b.receivedDate||'9999'))||String(a.expiryDate||'9999').localeCompare(String(b.expiryDate||'9999'))),selected=state.rawOverrides[`${lotId}|${req.key}`]||'';return `<label class="ps-raw-usage-row"><span><strong>${esc(req.name)}</strong><small>${niceRaw(req.quantity,req.unit)} ${tr('требуется','required','necesario')}</small></span><select data-raw-override="${esc(req.key)}"><option value="">${tr('FIFO автоматически','FIFO automatically','FIFO automático')}</option>${options.map(r=>`<option value="${esc(r.id)}" ${selected===r.id?'selected':''}>${esc(r.supplierLot||r.id)} · ${niceRaw(rawLotRemaining(r),r.unit)} ${tr('доступно','available','disponible')}</option>`).join('')}</select></label>`}).join(''):`<p>${tr('По рецептуре сырьё не найдено.','No raw materials found in the recipe.','No se encontraron materias primas en la receta.')}</p>`;document.querySelector('#psRawUsageDialog').showModal()}
