function niceRaw(q,u){q=num(q);return u==='g'?`${(q/1000).toFixed(q>=10000?1:3).replace(/\.0+$/,'')} kg`:u==='ml'?`${(q/1000).toFixed(q>=10000?1:3).replace(/\.0+$/,'')} l`:`${Math.round(q*100)/100} ${currentLang()==='en'?'pcs':currentLang()==='es'?'uds.':'шт.'}`}

