function injectRecipeTechButtons(){document.querySelectorAll('#recipeList .recipe-card').forEach((card,index)=>{const existing=card.querySelector('[data-ps-tech]')?.closest('.ps-recipe-extension');if(existing)existing.remove();const product=productList()[index];if(!product)return;const contains=computedContains(product.id),c=state.technicalCards[product.id]||{};card.insertAdjacentHTML('beforeend',`<div class="ps-recipe-extension"><div><strong>${tr('Техническая информация','Technical information','Información técnica')}</strong><small>${c.sku?`SKU ${esc(c.sku)} · `:''}${contains.length?`${esc(t('contains'))}: ${contains.map(allergenLabel).join(', ')}`:tr('Аллергены не указаны','Allergens not specified','Alérgenos no indicados')}</small></div><button type="button" class="secondary" data-ps-tech="${esc(product.id)}">${tr('Открыть','Open','Abrir')}</button></div>`)});document.querySelectorAll('[data-ps-tech]').forEach(b=>b.onclick=()=>openTech(b.dataset.psTech))}
function todaySummary(){const day=localDay(),bakes=bakeCompletions().some(x=>String(x.date)===day),cleaning=state.sanitary.some(x=>x.type==='cleaning'&&x.date===day),temps=state.sanitary.some(x=>x.type==='temperature'&&x.date===day),incidents=state.sanitary.filter(x=>x.type==='incident'&&x.status!=='closed').length,expiredDocs=state.documents.filter(x=>x.expiryDate&&x.expiryDate<day).length,openCapa=state.capaCases.filter(x=>x.status!=='closed').length,openRecalls=state.recalls.filter(x=>x.type==='actual'&&x.status!=='closed').length,trainingDue=state.trainingRecords.filter(x=>x.nextDue&&x.nextDue<day).length,equipmentDue=state.equipmentRecords.filter(x=>x.nextDue&&x.nextDue<day).length,expiringRaw=state.rawLots.filter(x=>x.expiryDate&&x.expiryDate>=day&&x.expiryDate<=datePlus(day,7)&&rawLotRemaining(x)>0).length;return{bakes,cleaning,temps,incidents,expiredDocs,openCapa,openRecalls,trainingDue,equipmentDue,expiringRaw}}
function safetyAlerts(){
 const day=localDay(),rows=[];
 state.rawLots.forEach(r=>{const left=rawLotRemaining(r);if(left<=0||!r.expiryDate)return;const days=Math.ceil((new Date(`${r.expiryDate}T12:00:00`)-new Date(`${day}T12:00:00`))/86400000);if(days<=7)rows.push({id:`raw:${r.id}:${r.expiryDate}`,critical:days<0,title:tr('Срок сырья','Raw-material expiry','Caducidad de materia prima'),text:days<0?`${r.ingredientName} · ${tr('срок истёк','expired','caducado')} ${formatDate(r.expiryDate)}`:`${r.ingredientName} · ${tr('до','until','hasta')} ${formatDate(r.expiryDate)}`,view:'ps-raw-lots'})});
 state.documents.forEach(d=>{const st=documentStatus(d);if(st==='active')return;rows.push({id:`doc:${d.id}:${st}:${d.expiryDate}`,critical:st==='expired',title:tr('Срок документа','Document expiry','Caducidad de documento'),text:`${d.name} · ${documentStatusLabel(st)}${d.expiryDate?` · ${formatDate(d.expiryDate)}`:''}`,view:'ps-documents'})});
 state.breadLots.filter(l=>l.blocked).forEach(l=>rows.push({id:`blocked:${l.id}:${l.blockAt||l.updatedAt}`,critical:true,title:tr('Партия заблокирована','Lot blocked','Lote bloqueado'),text:`${l.number} · ${productName(l.product)}${l.blockReason?` · ${l.blockReason}`:''}`,view:'ps-bread-lots'}));
 state.sanitary.filter(r=>r.type==='incident'&&r.status!=='closed').forEach(r=>rows.push({id:`incident:${r.id}:${r.status}:${r.updatedAt}`,critical:true,title:tr('Открыт санитарный инцидент','Sanitary incident open','Incidente sanitario abierto'),text:String(r.description||r.object||tr('Требуется действие','Action required','Se requiere acción')),view:'ps-sanitation'}));
 state.capaCases.filter(r=>r.status!=='closed'&&r.dueDate&&r.dueDate<day).forEach(r=>rows.push({id:`capa:${r.id}:${r.dueDate}:${r.updatedAt}`,critical:true,title:tr('Просрочено CAPA','CAPA overdue','CAPA vencida'),text:String(r.description||tr('Требуется корректирующее действие','Corrective action required','Se requiere acción correctiva')),view:'ps-capa'}));
 state.recalls.filter(r=>r.type==='actual'&&r.status!=='closed').forEach(r=>{const lot=state.breadLots.find(l=>l.id===r.lotId);rows.push({id:`recall:${r.id}:${r.status}:${r.updatedAt}`,critical:true,title:tr('Открыт отзыв продукции','Product recall open','Retirada de producto abierta'),text:`${lot?.number||'LOT'} · ${productName(r.product)} · ${r.reason}`,view:'ps-recalls'})});
 state.approvedSuppliers.forEach(r=>{if(r.status==='blocked')rows.push({id:`supplier:block:${r.id}:${r.updatedAt}`,critical:false,title:tr('Поставщик заблокирован','Supplier blocked','Proveedor bloqueado'),text:r.name,view:'ps-suppliers'});if(r.nextReview&&r.nextReview<day)rows.push({id:`supplier:review:${r.id}:${r.nextReview}`,critical:false,title:tr('Нужна проверка поставщика','Supplier review due','Revisión de proveedor pendiente'),text:`${r.name} · ${formatDate(r.nextReview)}`,view:'ps-suppliers'})});
 state.trainingRecords.filter(r=>r.nextDue&&r.nextDue<day).forEach(r=>rows.push({id:`training:${r.id}:${r.nextDue}`,critical:false,title:tr('Обучение просрочено','Training overdue','Formación vencida'),text:`${r.employee} · ${r.topic}`,view:'ps-training'}));
 state.equipmentRecords.filter(r=>r.nextDue&&r.nextDue<day).forEach(r=>rows.push({id:`equipment:${r.id}:${r.nextDue}`,critical:r.result==='out_of_service',title:tr('Проверка оборудования просрочена','Equipment check overdue','Revisión de equipo vencida'),text:`${r.equipment} · ${formatDate(r.nextDue)}`,view:'ps-equipment'}));
 const hour=new Date().getHours(),sum=todaySummary();if(hour>=18){if(!sum.cleaning)rows.push({id:`missed:cleaning:${day}`,critical:false,title:tr('Не выполнен обязательный контроль','Required control missed','Control obligatorio pendiente'),text:tr('Сегодня нет записи об уборке.','No cleaning record for today.','No hay registro de limpieza de hoy.'),view:'ps-sanitation'});if(!sum.temps)rows.push({id:`missed:temperature:${day}`,critical:false,title:tr('Не выполнен обязательный контроль','Required control missed','Control obligatorio pendiente'),text:tr('Сегодня нет записи температурного контроля.','No temperature-control record for today.','No hay registro de control de temperatura de hoy.'),view:'ps-sanitation'})}
 return rows;
}
function emitSafetyAlerts(){
 if(!initialized)return;const seen=parse(localStorage.getItem(ALERT_KEY),{}),cut=Date.now()-60*86400000;Object.keys(seen).forEach(k=>{if(num(seen[k])<cut)delete seen[k]});
 for(const a of safetyAlerts()){if(seen[a.id])continue;try{window.panoraEventNotifications?.notify?.(a.title,a.text,{priority:a.critical?'critical':'normal',type:a.critical?'error':'order',icon:a.critical?'⚠️':'🔔',view:a.view})}catch{}try{if(Notification.permission==='granted'&&navigator.serviceWorker?.controller)navigator.serviceWorker.controller.postMessage({type:'PANORA_SHOW_NOTIFICATION',payload:{title:a.title,body:a.text,url:`admin.html#${a.view}`,audience:'bakery',tag:`safety-${a.id}`,kind:'production-safety'}})}catch{}seen[a.id]=Date.now()}
 localStorage.setItem(ALERT_KEY,JSON.stringify(seen));
}
function datePlus(day,n){const d=new Date(`${day}T12:00:00`);d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)}
